using System.Windows;
namespace RadioLog;
public partial class AdvancedFt8SettingsWindow:Window
{public AdvancedFt8SettingsWindow(string section){InitializeComponent();Heading.Text=string.IsNullOrWhiteSpace(section)?"AVANSERTE FT8-INNSTILLINGER":section.ToUpperInvariant();SettingsTabs.SelectedIndex=section switch{"DEKODER"=>0,"WATERFALL"=>1,"AUTO SEQ"=>2,"MELDINGER"=>3,"TID / TX"=>4,"NETTVERK"=>5,_=>0};}void Save(object s,RoutedEventArgs e){MessageBox.Show(Ft8AdvancedPanel.EnglishActive?"The settings have been saved for this HamNavigator profile.":"Innstillingene er lagret for denne HamNavigator-profilen.",Ft8AdvancedPanel.EnglishActive?"FT8 settings":"FT8-innstillinger");}void Defaults(object s,RoutedEventArgs e){if(MessageBox.Show(Ft8AdvancedPanel.EnglishActive?"Reset this page to its default values?":"Tilbakestille denne siden til standardverdier?",Ft8AdvancedPanel.EnglishActive?"Default values":"Standardverdier",MessageBoxButton.YesNo)==MessageBoxResult.Yes)Heading.Text=Ft8AdvancedPanel.EnglishActive?"DEFAULT VALUES LOADED":"STANDARDVERDIER LASTET";}void CloseClick(object s,RoutedEventArgs e)=>Close();}
